def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.194.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.193.0"' not in init:
        sys.exit("ABORT: not at v3.193.0.")
    if "advanced" not in data:
        sys.exit("ABORT: advanced module not found in data file.")

    problems = _validate("SELL8", LESSONS_S8, QUESTIONS_S8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_S8))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — SELL8 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_S8)
    print(f"SELL 8 v3: {len(LESSONS_S8)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_S8):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["advanced"]["lessons"] = LESSONS_S8
    data["advanced"]["questions"] = bank
    data["advanced"]["desc"] = ("Advanced selling instruments in ZhiftERP: Product Bundles — the non-stock parent, the child table, the three document behaviours, the bundle-versus-production boundary test, availability arithmetic across components, returns under the package terms, and the bundle register; blanket orders — the recorded arrangement, call-offs at approved rates through the standard chain, governance and the monthly consumption read; sales person attribution with the integrity rule and the commission boundary; Selling Settings as control-register rows with the quarterly pass; and the consolidated selling calendar assembling every read from modules 1-7 into one operating rhythm.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.193.0"', '"3.194.0"'))
    print("  data: SELLING 8 lessons + bank REPLACED (style v3, textbook manual register) — SELLING TRACK COMPLETE")
    print("wrote __version__ -> 3.194.0")


if __name__ == "__main__":
    main()
